import{_ as o,r as s,o as p,c,e as a,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const b=JSON.parse('{"title":"Навигация - October CMS - 3.x","titleTemplate":false,"description":"Узнайте, как добавлять новые элементы меню в панель управления.","frontmatter":{"subtitle":"Узнайте, как добавлять новые элементы меню в панель управления."},"headers":[{"level":2,"title":"Счётчики навигации","slug":"счетчики-навигации","link":"#счетчики-навигации","children":[]},{"level":2,"title":"Типы отображения элементов","slug":"типы-отображения-элементов","link":"#типы-отображения-элементов","children":[]},{"level":2,"title":"Расширение меню панели управления","slug":"расширение-меню-панели-управления","link":"#расширение-меню-панели-управления","children":[]}],"relativePath":"3.x/ru/extend/backend/navigation.md","filePath":"3.x/ru/extend/backend/navigation.md"}'),r={name:"3.x/ru/extend/backend/navigation.md"};function u(g,n,d,k,m,h){const t=s("pre-heading"),e=s("post-heading");return p(),c("div",null,[a(t),n[0]||(n[0]=l("h1",null,"Навигация",-1)),a(e),n[1]||(n[1]=i(`<p>Плагины могут расширять меню навигации панели управления, переопределяя метод <code>registerNavigation</code> <a href="./../extending.html">файла регистрации плагина</a>. В этом разделе показано, как добавлять элементы меню в область навигации панели управления. Ниже приведён пример регистрации элемента навигации верхнего уровня с двумя элементами подменю.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerNavigation</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;blog&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Blog&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;url&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name static-context">Backend</span><span class="token operator">::</span><span class="token function">url</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme/blog/posts&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;icon&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;icon-pencil&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;permissions&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;acme.blog.*&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;order&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">500</span><span class="token punctuation">,</span>

            <span class="token string single-quoted-string">&#39;sideMenu&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
                <span class="token string single-quoted-string">&#39;posts&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
                    <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Posts&#39;</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">&#39;icon&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;icon-copy&#39;</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">&#39;url&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name static-context">Backend</span><span class="token operator">::</span><span class="token function">url</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme/blog/posts&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">&#39;permissions&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;acme.blog.access_posts&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
                <span class="token punctuation">]</span><span class="token punctuation">,</span>
                <span class="token string single-quoted-string">&#39;categories&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
                    <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Categories&#39;</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">&#39;icon&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;icon-copy&#39;</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">&#39;url&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name static-context">Backend</span><span class="token operator">::</span><span class="token function">url</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme/blog/categories&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">&#39;permissions&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;acme.blog.access_categories&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
                <span class="token punctuation">]</span>
            <span class="token punctuation">]</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>При регистрации навигации панели управления вы можете использовать <a href="./../system/localization.html">строки локализации</a> для значений <code>label</code>. Навигация панели управления также может контролироваться значениями <code>permissions</code>, соответствующими определённым <a href="./permissions.html">разрешениям пользователей панели управления</a>. Порядок отображения навигации в общем меню контролируется значением <code>order</code>. Большие числа означают, что элемент появится позже в порядке элементов меню, а меньшие — что он появится раньше.</p><p>Для отображения элементов подменю вы можете установить контекст навигации в <a href="./../system/controllers.html">контроллере панели управления</a> с помощью метода <code>BackendMenu::setContext</code>. Это сделает родительский элемент меню активным и отобразит дочерние элементы в боковом меню.</p><div class="table"><table tabindex="0"><thead><tr><th>Свойство</th><th>Описание</th></tr></thead><tbody><tr><td><strong>label</strong></td><td>указывает ключ строки локализации метки меню, обязательно.</td></tr><tr><td><strong>order</strong></td><td>числовой вес для определения порядка отображения.</td></tr><tr><td><strong>icon</strong></td><td>имя иконки из <a href="./../../element/available-icons.html">коллекции иконок October CMS</a>, необязательно.</td></tr><tr><td><strong>iconSvg</strong></td><td>SVG-иконка для использования вместо стандартной иконки, SVG-иконка должна быть прямоугольной и может поддерживать цвета, необязательно.</td></tr><tr><td><strong>url</strong></td><td>URL, на который должен указывать элемент меню (например, <code>Backend::url(&#39;author/plugin/controller/action&#39;)</code>), обязательно.</td></tr><tr><td><strong>counter</strong></td><td>числовое значение для отображения рядом с иконкой меню. Значение должно быть числом или вызываемым объектом, возвращающим число, необязательно.</td></tr><tr><td><strong>counterLabel</strong></td><td>строковое значение для описания числовой ссылки в counter, необязательно.</td></tr><tr><td><strong>attributes</strong></td><td>ассоциативный массив атрибутов и значений для применения к элементу меню, необязательно.</td></tr><tr><td><strong>permissions</strong></td><td>массив разрешений, которые пользователь панели управления должен иметь для просмотра элемента меню (Примечание: прямой доступ по URL всё равно требует отдельных проверок разрешений), необязательно.</td></tr><tr><td><strong>sideMenu</strong></td><td>массив элементов подменю, использующих ту же конфигурацию, что и родительские элементы, необязательно.</td></tr><tr><td><strong>itemType</strong></td><td>указывает тип отображения элемента, только для элементов подменю. Поддерживаемые: <code>primary</code>, <code>link</code>, <code>ruler</code>, <code>section</code>. По умолчанию: <code>link</code>.</td></tr></tbody></table></div><p>Следующие значения генерируются системой и не предоставляются при регистрации элементов навигации.</p><div class="table"><table tabindex="0"><thead><tr><th>Ключ</th><th>Описание</th></tr></thead><tbody><tr><td><strong>code</strong></td><td>строковое значение, действующее как уникальный идентификатор для этого элемента меню.</td></tr><tr><td><strong>owner</strong></td><td>строковое значение, указывающее владельца элемента меню — плагин или модуль в формате «Author.Plugin».</td></tr></tbody></table></div><h2 id="счетчики-навигации"><a href="#счетчики-навигации" class="header-anchor">#</a> Счётчики навигации</h2><p>Элементы навигации поддерживают указание счётчика, чтобы показать, что есть элементы, требующие внимания. Эти свойства доступны как для родительских, так и для дочерних элементов меню. Используйте <strong>counter</strong> и <strong>counterLabel</strong> для отображения числового счётчика.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;blog&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
    <span class="token comment">// ...</span>
    <span class="token string single-quoted-string">&#39;counter&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Author<span class="token punctuation">\\</span>Plugin<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>MyMenuCounterService</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;getCounterMethod&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;counterLabel&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Label describing a dynamic menu counter&#39;</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">,</span>
</code></pre></div><h2 id="типы-отображения-элементов"><a href="#типы-отображения-элементов" class="header-anchor">#</a> Типы отображения элементов</h2><p>Элементы подменю поддерживают различные типы отображения с помощью свойства <code>itemType</code>, включая элементы пользовательского интерфейса. Установите тип <code>section</code> для отображения секции навигации. Добавление префикса подчёркивания (<code>_</code>) к имени ключа — хороший способ обозначить, что это элемент интерфейса.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;_section1&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;itemType&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;section&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Advanced&#39;</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">,</span>
</code></pre></div><p>Может быть полезно сочетать секцию с разделителем навигации, расположенным над ней. Установите тип <code>ruler</code> для отображения разделителя.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;_ruler1&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;itemType&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;ruler&#39;</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">,</span>
</code></pre></div><p>Для отображения призыва к действию установите тип <code>primary</code>, чтобы отобразить ссылку как кнопку основного действия.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;people_create&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;New Person&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;icon&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;icon-plus&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;url&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name static-context">Backend</span><span class="token operator">::</span><span class="token function">url</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme/blog/people/create&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;itemType&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;primary&#39;</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">,</span>
</code></pre></div><h2 id="расширение-меню-панели-управления"><a href="#расширение-меню-панели-управления" class="header-anchor">#</a> Расширение меню панели управления</h2><p><a href="./../extending.html">Обработчик события</a> <code>backend.menu.extendItems</code> может использоваться для модификации существующих элементов навигации после того, как система и плагины зарегистрировали свои элементы навигации. Событие возвращает экземпляр менеджера навигации <code>$manager</code>, поддерживающий следующие методы.</p><div class="table"><table tabindex="0"><thead><tr><th>Метод</th><th>Описание</th></tr></thead><tbody><tr><td><strong>addMainMenuItems($owner, $definitions)</strong></td><td>Добавить или обновить определение главного меню</td></tr><tr><td><strong>getMainMenuItem($owner, $code)</strong></td><td>Получить существующее определение главного меню</td></tr><tr><td><strong>removeMainMenuItem($owner, $code)</strong></td><td>Удалить существующее определение главного меню</td></tr><tr><td><strong>addSideMenuItems($owner, $code, $definitions)</strong></td><td>Добавить или обновить определение бокового меню</td></tr><tr><td><strong>getSideMenuItem($owner, $code, $sideCode)</strong></td><td>Получить существующее определение бокового меню</td></tr><tr><td><strong>removeSideMenuItem($owner, $code, $sideCode)</strong></td><td>Удалить существующее определение бокового меню</td></tr></tbody></table></div><p>При получении элемента меню объект поддерживает цепочку методов для обновления его свойств. Следующий пример заменит метку Редактора на <strong>Code Editor</strong>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;backend.menu.extendItems&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$manager</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$manager</span><span class="token operator">-&gt;</span><span class="token function">getMainMenuItem</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;October.Editor&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;editor&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">label</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Code Editor&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Следующий пример изменит метку на <strong>News</strong> и добавит счётчик <strong>9</strong> к плагину Acme Blog.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;backend.menu.extendItems&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$manager</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$manager</span><span class="token operator">-&gt;</span><span class="token function">getMainMenuItem</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Acme.Blog&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;blog&#39;</span><span class="token punctuation">)</span>
        <span class="token operator">-&gt;</span><span class="token function">getSideMenuItem</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;posts&#39;</span><span class="token punctuation">)</span>
        <span class="token operator">-&gt;</span><span class="token function">label</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;News&#39;</span><span class="token punctuation">)</span>
        <span class="token operator">-&gt;</span><span class="token function">counter</span><span class="token punctuation">(</span><span class="token number">9</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Аналогично мы можем удалить элементы меню, используя то же событие. Следующий пример удалит все элементы, один элемент и несколько элементов соответственно.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;backend.menu.extendItems&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$manager</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$manager</span><span class="token operator">-&gt;</span><span class="token function">removeMainMenuItem</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Acme.Blog&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;blog&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token variable">$manager</span><span class="token operator">-&gt;</span><span class="token function">removeSideMenuItem</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Acme.Blog&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;blog&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;posts&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token variable">$manager</span><span class="token operator">-&gt;</span><span class="token function">removeSideMenuItems</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Acme.Blog&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;blog&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;posts&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;categories&#39;</span>
    <span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div>`,26))])}const v=o(r,[["render",u]]);export{b as __pageData,v as default};
